import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { LiteratureRecord, evaluate } from "../src";

// data/records.json is generated by scripts/ (docs/RECORDS.md). These checks guard the generated
// file itself, so a change to an importer that loses a proof claim or stores coordinates the
// site would reject is caught here and not on the site.
const { records } = JSON.parse(readFileSync(new URL("../../../data/records.json", import.meta.url), "utf8")) as {
  records: LiteratureRecord[];
};
const find = (N: number, M: number, P: number) => records.find((r) => r.N === N && r.M === M && r.P === P);

describe("data/records.json", () => {
  it("never stores a source's proof claim as best_known", () => {
    // \b keeps "Improved by ..." out. "Proved by F. Fodor in 2003." was once lost at the initial.
    const lost = records.filter((r) => /\bprove[dn]\b/i.test(r.citation ?? "") && r.status === "best_known");
    expect(lost.map((r) => `${r.N}/${r.M}/${r.P}: ${r.citation}`)).toEqual([]);
  });

  it("records the published proofs for 13 and 19 circles in a circle as proven", () => {
    for (const P of [13, 19]) {
      const r = find(0, 0, P)!;
      expect(r.citation).toMatch(/Proved by F\. Fodor in (1999|2003)\./);
      expect(r.status).toBe("proven");
    }
  });

  it("keeps recent proof claims flagged", () => {
    const flagged = records.filter((r) => r.status === "proven_unrefereed");
    expect(flagged.length).toBeGreaterThan(0);
    for (const r of flagged) expect(Number(/\bProved by\b.*?\b(\d{4})\b/.exec(r.citation ?? "")?.[1])).toBeGreaterThanOrEqual(2023);
  });

  it("records Hosono's eight computer-assisted triangle proofs, and no others", () => {
    const hosono = JSON.parse(readFileSync(new URL("../../../data/sources/hosono.json", import.meta.url), "utf8")) as {
      records: { P: number; value: number }[];
      not_proven: { N: number; M: number; P: number }[];
    };
    const sides: Record<number, number> = {
      3: 1.5 + Math.sqrt(3), 4: 3 + 2 / Math.sqrt(3), 6: 2 + 4 / Math.sqrt(3), 7: 4 + 2 / Math.sqrt(3),
      11: 5 + 2 / Math.sqrt(3), 16: 6 + 2 / Math.sqrt(3), 22: 7 + 2 / Math.sqrt(3), 29: 8 + 2 / Math.sqrt(3),
    };
    expect(hosono.records.map((r) => r.P)).toEqual(Object.keys(sides).map(Number));
    for (const [P, side] of Object.entries(sides)) {
      const r = find(4, 3, Number(P))!;
      expect(r.status).toBe("proven_unrefereed");
      expect(r.note).toContain("Hiroaki Hosono, square-packing");
      expect(r.note).toContain("triangle-v1");
      // the stored value is the source's truncated print, below the proven side by less than one unit of its precision
      expect(side - r.value).toBeGreaterThanOrEqual(-1e-9);
      expect(side - r.value).toBeLessThanOrEqual(10 ** -r.display_precision);
      expect(hosono.records.find((h) => h.P === Number(P))!.value).toBe(side);
    }
    // the lower bound of 6 squares has no Lean proof yet; the others do
    expect(find(4, 3, 6)!.note).toContain("no Lean 4 proof");
    expect(find(4, 3, 7)!.note).toContain("also checked in Lean 4");
    // Hosono's repository lists 5 squares as not done, although Friedman's page says 2 to 7 are proved
    expect(hosono.not_proven).toEqual([expect.objectContaining({ N: 4, M: 3, P: 5 })]);
    for (const P of [5, 37, 46]) expect(find(4, 3, P)!.status).toBe("best_known");
    expect(records.filter((r) => r.N === 4 && r.M === 3 && r.status === "proven_unrefereed").length).toBe(8);
  });

  it("holds no value below the bound from a proven circle record", () => {
    // an M-gon of side s lies in its circumcircle, of radius s / (2 sin(π/M)); a circle record is its diameter (scripts/build-records.ts)
    const below = records.filter((r) => {
      const circle = find(r.N, 0, r.P);
      if (r.M === 0 || circle?.status !== "proven") return false;
      return r.value + 2 * 10 ** -r.display_precision < Math.sin(Math.PI / r.M) * circle.value;
    });
    expect(below.map((r) => `${r.N}/${r.M}/${r.P}: ${r.display}`)).toEqual([]);
  });

  it("gives two pentagons in a hexagon and in an octagon PolyPack's own packings, not claimed optimal", () => {
    // Friedman's 1.53879+ and 1.17774+ lie below that bound and are left out
    for (const M of [6, 8]) {
      const r = find(5, M, 2)!;
      expect(r.status).toBe("best_known");
      expect(r.source_name).toMatch(/^PolyPack/);
      const e = evaluate({ N: 5, M, P: 2, pieces: r.pieces!, container_phi: r.container_phi! });
      expect(e.valid).toBe(true);
      expect(Math.abs(e.score! - r.value)).toBeLessThan(1e-12);
    }
  });

  it("takes Berthold et al.'s polygon packings only where no other source has a value: every pair with a heptagon", () => {
    const kamp = records.filter((r) => r.source_name.startsWith("Berthold, Kamp, Mexi, Pokutta and Polik"));
    // 3- to 6-gons in a heptagon, heptagons in 3- to 7-gons, n = 1..30
    expect(kamp.length).toBe(9 * 30);
    expect(
      kamp.every((r) => (r.N === 7 || r.M === 7) && r.N <= 7 && r.M <= 7 && r.P <= 30 && r.pieces?.length === r.P),
    ).toBe(true);
    // the supplement claims no optimality; one heptagon in a heptagon is a tiling, at its exact value
    expect(kamp.filter((r) => r.status !== "best_known").map((r) => [r.N, r.M, r.P, r.status, r.value])).toEqual([
      [7, 7, 1, "trivial_tiling", 1],
    ]);
    // a value of theirs never replaced another source's digits
    expect(records.filter((r) => /More digits .* Berthold/.test(r.conversion_note))).toEqual([]);
  });

  it("has coordinates for every circles-in-a-circle record up to P = 500", () => {
    for (let P = 1; P <= 500; P++) {
      const r = find(0, 0, P);
      expect(r?.pieces?.length, `0/0/${P}`).toBe(P);
    }
  });

  it("stores only coordinates that the site's checker accepts and that reproduce the value", () => {
    const bad: string[] = [];
    for (const r of records) {
      if (!r.pieces) continue;
      const e = evaluate({ N: r.N, M: r.M, P: r.P, pieces: r.pieces, container_phi: r.container_phi ?? 0 });
      // the rule of scripts/build-records.ts: 1e-8, or the printed precision where that is coarser
      const tolerance = Math.max(1e-8, 2 * 10 ** -r.display_precision);
      if (!e.valid || !(Math.abs(e.score! - r.value) <= tolerance)) bad.push(`${r.N}/${r.M}/${r.P}`);
    }
    expect(bad).toEqual([]);
  });

  it("attaches solver-constructed coordinates only where they reach the published value", () => {
    // data/sources/constructed.json (scripts/construct-coordinates.ts): a packing of the published
    // size within 10^-display_precision, never above it, at the stored container angle. The tolerance is in the
    // source's unit, so it is doubled for a circle container, whose size is the diameter (sourceTolerance in scripts/units.ts)
    const constructed = records.filter((r) => /^Coordinates constructed by PolyPack \(/.test(r.coordinates_note ?? ""));
    const { constructions } = JSON.parse(
      readFileSync(new URL("../../../data/sources/constructed.json", import.meta.url), "utf8"),
    ) as { constructions: { N: number; M: number; P: number }[] };
    expect(constructed.length).toBeGreaterThan(0);
    expect(constructed.length).toBeLessThanOrEqual(constructions.length);
    const bad: string[] = [];
    for (const r of constructed) {
      const e = evaluate({ N: r.N, M: r.M, P: r.P, pieces: r.pieces!, container_phi: r.container_phi! });
      if (!e.valid || !(Math.abs(e.score! - r.value) <= 10 ** -r.display_precision * (r.N > 0 && r.M === 0 ? 2 : 1))) bad.push(`${r.N}/${r.M}/${r.P}`);
      if (!constructions.some((c) => c.N === r.N && c.M === r.M && c.P === r.P)) bad.push(`${r.N}/${r.M}/${r.P}: not in constructed.json`);
    }
    expect(bad).toEqual([]);
  });
});
